    fn associativity(&self) -> Associativity {
        Associativity::Left
    }

    /// Builds an AST expression for the infix operator.
    fn into_expression(self, lhs: ast::Expression, rhs: ast::Expression) -> ast::Expression {
        use ast::Operator::*;
        match self {
            Self::Add => Operator::Add(Box::new(lhs), Box::new(rhs)),
            Self::And => Operator::And(Box::new(lhs), Box::new(rhs)),
            Self::Divide => Operator::Divide(Box::new(lhs), Box::new(rhs)),
