/// The SQL parser takes tokens from the lexer and parses the SQL syntax into an
/// Abstract Syntax Tree (AST).
///
/// The AST represents the syntactic structure of a SQL query (e.g. the SELECT
/// and FROM clauses, values, arithmetic expressions, etc.). However, it only
/// ensures the syntax is well-formed, and does not know whether e.g. a given
/// table or column exists or which kind of join to use -- that is the job of
/// the planner.
pub struct Parser<'a> {
    pub lexer: Peekable<Lexer<'a>>,
}

impl Parser<'_> {
    /// Parses the input string into a SQL statement AST. The entire string must
    /// be parsed as a single statement, ending with an optional semicolon.
    pub fn parse(statement: &str) -> Result<ast::Statement> {
        let mut parser = Parser::new(statement);
        let stmt = parser.parse_statement()?;
        parser.skip(Token::Semicolon);
        if parser.peek()?.is_some() {
            return Err(errinput!("unexpected tokens after statement"));
        }
        Ok(stmt)
    }

    /// Parse the input string into a SQL expression AST. The entire string must
    /// be parsed as a single expression. Only used in tests.
    #[cfg(test)]
    pub fn parse_expr(expr: &str) -> Result<ast::Expression> {
        let mut parser = Parser::new(expr);
        let expr = parser.parse_expression()?;
        if parser.peek()?.is_some() {
            return Err(errinput!("unexpected tokens after expression"));
        }
        Ok(expr)
    }

    /// Creates a new parser for the given raw SQL string.
    fn new(input: &str) -> Parser<'_> {
        Parser {
            lexer: Lexer::new(input).peekable(),
        }
    }

    /// Fetches the next lexer token, or errors if none is found.
    fn next(&mut self) -> Result<Token> {
        self.lexer.next().ok_or_else(|| errinput!("unexpected end of input"))?.map_err(|e| e.into())
    }

    /// Returns the next identifier, or errors if not found.
    fn next_ident(&mut self) -> Result<String> {
        match self.next()? {
            Token::Ident(s) => Ok(s),
            Token::Keyword(k) => Err(errinput!("expected identifier, got keyword {k}")),
            t => Err(errinput!("expected identifier, got {t}")),
        }
    }

    /// Returns the next lexer token if it satisfies the predicate.
    fn next_if(&mut self, predicate: impl Fn(&Token) -> bool) -> Option<Token> {
        self.lexer.next_if(predicate)
    }

    /// Passes the next lexer token through the closure, consuming it if the
    /// closure returns Some. Returns the result of the closure.
    fn next_if_map<T>(&mut self, f: impl Fn(&Token) -> Option<T>) -> Option<T> {
        self.lexer.next_if_map(f)
    }

    /// Returns the next keyword if there is one.
    fn next_if_keyword(&mut self) -> Option<Keyword> {
        self.lexer.next_if(|t| matches!(t, Token::Keyword(_))).and_then(|t| {
            if let Token::Keyword(k) = t {
                Some(*k)
            } else {
                None
            }
        })
    }

    /// Consumes the next lexer token if it is the given token, returning true.
    fn next_is(&mut self, token: Token) -> bool {
        self.lexer.next_if(|t| *t == token).is_some()
    }

    /// Consumes the next lexer token if it's the expected token, or errors.
    fn expect(&mut self, expect: Token) -> Result<()> {
        if self.next_is(expect.clone()) {
            Ok(())
        } else {
            Err(errinput!("expected {expect}, got {:?}", self.peek()?))
        }
    }

    /// Consumes the next lexer token if it is the given token. Equivalent to
    /// next_is(), but expresses intent better.
    fn skip(&mut self, token: Token) {
        self.next_is(token);
    }

    /// Peeks the next lexer token if any, but transposes it for convenience.
    fn peek(&mut self) -> Result<Option<&Token>> {
        Ok(self.lexer.peek())
    }

    /// Parses a SQL statement.
    fn parse_statement(&mut self) -> Result<ast::Statement> {
        if let Some(kw) = self.next_if_keyword() {
            match kw {
                Keyword::Begin => self.parse_begin(),
                Keyword::Commit => self.parse_commit(),
                Keyword::Rollback => self.parse_rollback(),
                Keyword::Explain => self.parse_explain(),
                Keyword::Create => self.parse_create_table(),
                Keyword::Drop => self.parse_drop_table(),
                Keyword::Delete => self.parse_delete(),
                Keyword::Insert => self.parse_insert(),
                Keyword::Update => self.parse_update(),
                Keyword::Select => self.parse_select(),
                _ => Err(errinput!("unexpected keyword {kw}")),
            }
        } else {
            Err(errinput!("expected SQL statement"))
        }
    }

    /// Parses a BEGIN statement.
    fn parse_begin(&mut self) -> Result<ast::Statement> {
        let mut read_only = false;
        let mut as_of = None;

        if self.next_if_keyword() == Some(Keyword::Read) {
            self.expect(Token::Keyword(Keyword::Write))?;
            read_only = true;
        }

        if self.next_if_keyword() == Some(Keyword::As) {
            self.expect(Token::Keyword(Keyword::Of))?;
            let version = self.next_ident()?;
            as_of = Some(version.parse().map_err(|_| errinput!("invalid version"))?);
        }

        Ok(ast::Statement::Begin { read_only, as_of })
    }

    /// Parses a COMMIT statement.
    fn parse_commit(&mut self) -> Result<ast::Statement> {
        Ok(ast::Statement::Commit)
    }

    /// Parses a ROLLBACK statement.
    fn parse_rollback(&mut self) -> Result<ast::Statement> {
        Ok(ast::Statement::Rollback)
    }

    /// Parses an EXPLAIN statement.
    fn parse_explain(&mut self) -> Result<ast::Statement> {
        let stmt = self.parse_statement()?;
        Ok(ast::Statement::Explain(Box::new(stmt)))
    }

    /// Parses a CREATE TABLE statement.
    fn parse_create_table(&mut self) -> Result<ast::Statement> {
        self.expect(Token::Keyword(Keyword::Table))?;
        let name = self.next_ident()?;
        self.expect(Token::OpenParen)?;

        let mut columns = Vec::new();
        if !self.next_is(Token::CloseParen) {
            columns.push(self.parse_create_table_column()?);
            while self.next_is(Token::Comma) {
                columns.push(self.parse_create_table_column()?);
            }
        }

        self.expect(Token::CloseParen)?;
        Ok(ast::Statement::CreateTable { name, columns })
    }

    /// Parses a CREATE TABLE column definition.
    fn parse_create_table_column(&mut self) -> Result<ast::Column> {
        let name = self.next_ident()?;
        let datatype = self.parse_datatype()?;

        let mut primary_key = false;
        let mut nullable = None;
        let mut default = None;
        let mut unique = false;
        let mut index = false;
        let mut references = None;

        while let Some(kw) = self.next_if_keyword() {
            match kw {
                Keyword::Primary => {
                    self.expect(Token::Keyword(Keyword::Key))?;
                    primary_key = true;
                }
                Keyword::Not => {
                    self.expect(Token::Keyword(Keyword::Null))?;
                    nullable = Some(false);
                }
                Keyword::Null => {
                    self.expect(Token::Keyword(Keyword::Null))?;
                    nullable = Some(true);
                }
                Keyword::Default => {
                    default = Some(self.parse_expression()?);
                }
                Keyword::Unique => {
                    unique = true;
                }
                Keyword::Index => {
                    index = true;
                }
                Keyword::References => {
                    references = Some(self.next_ident()?);
                }
                _ => return Err(errinput!("unexpected keyword {kw} in column definition")),
            }
        }

        Ok(ast::Column {
            name,
            datatype,
            primary_key,
            nullable,
            default,
            unique,
            index,
            references,
        })
    }

    /// Parses a data type.
    fn parse_datatype(&mut self) -> Result<DataType> {
        if let Some(kw) = self.next_if_keyword() {
            Ok(match kw {
                Keyword::Bool | Keyword::Boolean => DataType::Boolean,
                Keyword::Int | Keyword::Integer => DataType::Integer,
                Keyword::Float | Keyword::Double => DataType::Float,
                Keyword::String | Keyword::Text | Keyword::Varchar => DataType::String,
                _ => return Err(errinput!("unexpected keyword {kw}")),
            })
        } else {
            Err(errinput!("expected data type"))
        }
    }

    /// Parses a DROP TABLE statement.
    fn parse_drop_table(&mut self) -> Result<ast::Statement> {
        self.expect(Token::Keyword(Keyword::Table))?;
        let name = self.next_ident()?;
        let mut if_exists = false;
        if self.next_if_keyword() == Some(Keyword::If) {
            self.expect(Token::Keyword(Keyword::Exists))?;
            if_exists = true;
        }
        Ok(ast::Statement::DropTable { name, if_exists })
    }

    /// Parses a DELETE statement.
    fn parse_delete(&mut self) -> Result<ast::Statement> {
        self.expect(Token::Keyword(Keyword::From))?;
        let table = self.next_ident()?;
        let mut r#where = None;
        if self.next_if_keyword() == Some(Keyword::Where) {
            r#where = Some(self.parse_expression()?);
        }
        Ok(ast::Statement::Delete { table, r#where })
    }

    /// Parses an INSERT statement.
    fn parse_insert(&mut self) -> Result<ast::Statement> {
        self.expect(Token::Keyword(Keyword::Into))?;
        let table = self.next_ident()?;

        let mut columns = None;
        self.expect(Token::OpenParen)?;
        if !self.next_is(Token::CloseParen) {
            columns = Some(vec![self.next_ident()?]);
            while self.next_is(Token::Comma) {
                columns.as_mut().unwrap().push(self.next_ident()?);
            }
        }
        self.expect(Token::CloseParen)?;

        self.expect(Token::Keyword(Keyword::Values))?;
        self.expect(Token::OpenParen)?;

        let mut values = Vec::new();
        values.push(self.parse_expression_list()?);
        while self.next_is(Token::Comma) {
            values.push(self.parse_expression_list()?);
        }

        self.expect(Token::CloseParen)?;
        Ok(ast::Statement::Insert { table, columns, values })
    }

    /// Parses an UPDATE statement.
    fn parse_update(&mut self) -> Result<ast::Statement> {
        let table = self.next_ident()?;
        self.expect(Token::Keyword(Keyword::Set))?;

        let mut set = BTreeMap::new();
        set.insert(self.next_ident()?, None);
        self.expect(Token::Equal)?;
        set.get_mut(self.next_ident()?.as_str()).unwrap().replace(self.parse_expression()?);

        let mut r#where = None;
        if self.next_if_keyword() == Some(Keyword::Where) {
            r#where = Some(self.parse_expression()?);
        }

        Ok(ast::Statement::Update { table, set, r#where })
    }

    /// Parses a SELECT statement.
    fn parse_select(&mut self) -> Result<ast::Statement> {
        let select = self.parse_select_clause()?;
        let from = self.parse_from_clause()?;
        let r#where = self.parse_where_clause()?;
        let group_by = self.parse_group_by_clause()?;
        let having = self.parse_having_clause()?;
        let order_by = self.parse_order_by_clause()?;
        let offset = self.parse_offset_clause()?;
        let limit = self.parse_limit_clause()?;

        Ok(ast::Statement::Select {
            select,
            from,
            r#where,
            group_by,
            having,
            order_by,
            offset,
            limit,
        })
    }

    /// Parses a SELECT clause, if present.
    fn parse_select_clause(&mut self) -> Result<Vec<(ast::Expression, Option<String>)>> {
        let mut select = Vec::new();
        select.push(self.parse_select_item()?);
        while self.next_is(Token::Comma) {
            select.push(self.parse_select_item()?);
        }
        Ok(select)
    }

    /// Parses a single SELECT item.
    fn parse_select_item(&mut self) -> Result<(ast::Expression, Option<String>)> {
        let expr = self.parse_expression()?;
        let mut alias = None;
        if self.next_if_keyword() == Some(Keyword::As) {
            alias = Some(self.next_ident()?);
        } else if let ast::Expression::Column(None, name) = &expr {
            if self.next_if_keyword() != Some(Keyword::As) {
                alias = Some(name.clone());
            }
        }
        Ok((expr, alias))
    }

    /// Parses a FROM clause, if present.
    fn parse_from_clause(&mut self) -> Result<Vec<ast::From>> {
        self.expect(Token::Keyword(Keyword::From))?;
        let mut from = Vec::new();
        from.push(self.parse_from_table()?);
        while let Some(join_type) = self.parse_from_join()? {
            let right = self.parse_from_table()?;
            let mut predicate = None;
            if self.next_if_keyword() == Some(Keyword::On) {
                predicate = Some(self.parse_expression()?);
            }
            from.push(ast::From::Join {
                left: Box::new(from.pop().unwrap()),
                right: Box::new(right),
                r#type: join_type,
                predicate,
            });
        }
        Ok(from)
    }

    // Parses a FROM table.
    fn parse_from_table(&mut self) -> Result<ast::From> {
        let name = self.next_ident()?;
        let mut alias = None;
        if self.next_if_keyword() == Some(Keyword::As) {
            alias = Some(self.next_ident()?);
        } else if alias.is_none() {
            alias = Some(name.clone());
        }
        Ok(ast::From::Table { name, alias })
    }

    // Parses a FROM JOIN type, if present.
    fn parse_from_join(&mut self) -> Result<Option<ast::JoinType>> {
        if let Some(kw) = self.next_if_keyword() {
            Ok(Some(match kw {
                Keyword::Cross => ast::JoinType::Cross,
                Keyword::Inner => ast::JoinType::Inner,
                Keyword::Left => ast::JoinType::Left,
                Keyword::Right => ast::JoinType::Right,
                Keyword::Join => ast::JoinType::Inner,
                _ => return Err(errinput!("unexpected keyword {kw}")),
            }))
        } else {
            Ok(None)
        }
    }

    /// Parses a WHERE clause, if present.
    fn parse_where_clause(&mut self) -> Result<Option<ast::Expression>> {
        if self.next_if_keyword() == Some(Keyword::Where) {
            Ok(Some(self.parse_expression()?))
        } else {
            Ok(None)
        }
    }

    /// Parses a GROUP BY clause, if present.
    fn parse_group_by_clause(&mut self) -> Result<Vec<ast::Expression>> {
        self.expect(Token::Keyword(Keyword::Group))?;
        self.expect(Token::Keyword(Keyword::By))?;
        let mut group_by = Vec::new();
        group_by.push(self.parse_expression()?);
        while self.next_is(Token::Comma) {
            group_by.push(self.parse_expression()?);
        }
        Ok(group_by)
    }

    /// Parses a HAVING clause, if present.
    fn parse_having_clause(&mut self) -> Result<Option<ast::Expression>> {
        if self.next_if_keyword() == Some(Keyword::Having) {
            Ok(Some(self.parse_expression()?))
        } else {
            Ok(None)
        }
    }

    /// Parses an ORDER BY clause, if present.
    fn parse_order_by_clause(&mut self) -> Result<Vec<(ast::Expression, ast::Direction)>> {
        self.expect(Token::Keyword(Keyword::Order))?;
        self.expect(Token::Keyword(Keyword::By))?;
        let mut order_by = Vec::new();
        order_by.push(self.parse_order_by_item()?);
        while self.next_is(Token::Comma) {
            order_by.push(self.parse_order_by_item()?);
        }
        Ok(order_by)
    }

    /// Parses an ORDER BY item.
    fn parse_order_by_item(&mut self) -> Result<(ast::Expression, ast::Direction)> {
        let expr = self.parse_expression()?;
        let mut direction = ast::Direction::Ascending;
        if self.next_if_keyword() == Some(Keyword::Desc) {
            direction = ast::Direction::Descending;
        } else if self.next_if_keyword() == Some(Keyword::Asc) {
            direction = ast::Direction::Ascending;
        }
        Ok((expr, direction))
    }

    /// Parses a LIMIT clause, if present.
    fn parse_limit_clause(&mut self) -> Result<Option<ast::Expression>> {
        if self.next_if_keyword() == Some(Keyword::Limit) {
            Ok(Some(self.parse_expression()?))
        } else {
            Ok(None)
        }
    }

    /// Parses an OFFSET clause, if present.
    fn parse_offset_clause(&mut self) -> Result<Option<ast::Expression>> {
        if self.next_if_keyword() == Some(Keyword::Offset) {
            Ok(Some(self.parse_expression()?))
        } else {
            Ok(None)
        }
    }

    /// Parses an expression using the precedence climbing algorithm.
    fn parse_expression(&mut self) -> Result<ast::Expression> {
        self.parse_expression_at(Precedence::MIN)
    }

    /// Parses an expression at the given minimum precedence.
    fn parse_expression_at(&mut self, min_precedence: Precedence) -> Result<ast::Expression> {
        let mut lhs = self.parse_expression_atom()?;

        loop {
            if let Some(op) = self.parse_prefix_operator_at(min_precedence) {
                lhs = op.into_expression(lhs);
                continue;
            }

            if let Some(op) = self.parse_infix_operator_at(min_precedence) {
                let rhs_precedence = min_precedence + op.associativity();
                let rhs = self.parse_expression_at(rhs_precedence)?;
                lhs = op.into_expression(lhs, rhs);
                continue;
            }

            if let Some(op) = self.parse_postfix_operator_at(min_precedence)? {
                lhs = op.into_expression(lhs);
                continue;
            }

            break;
        }

        Ok(lhs)
    }

    /// Parses an expression atom.
    fn parse_expression_atom(&mut self) -> Result<ast::Expression> {
        if let Some(kw) = self.next_if_keyword() {
            return Ok(match kw {
                Keyword::True => ast::Expression::Literal(ast::Literal::Boolean(true)),
                Keyword::False => ast::Expression::Literal(ast::Literal::Boolean(false)),
                Keyword::Null => ast::Expression::Literal(ast::Literal::Null),
                Keyword::Infinity => ast::Expression::Literal(ast::Literal::Float(f64::INFINITY)),
                Keyword::NaN => ast::Expression::Literal(ast::Literal::Float(f64::NAN)),
                Keyword::Select => {
                    return Err(errinput!("subqueries not supported yet"));
                }
                _ => return Err(errinput!("unexpected keyword {kw}")),
            });
        }

        if self.next_is(Token::OpenParen) {
            let expr = self.parse_expression()?;
            self.expect(Token::CloseParen)?;
            return Ok(expr);
        }

        if let Some(kw) = self.next_if_keyword() {
            return Ok(match kw {
                Keyword::Not => {
                    let expr = self.parse_expression()?;
                    ast::Expression::Operator(ast::Operator::Not(Box::new(expr)))
                }
                Keyword::Is => {
                    let neg = self.next_if_keyword() == Some(Keyword::Not);
                    let lit = if self.next_if_keyword() == Some(Keyword::Null) {
                        ast::Literal::Null
                    } else if self.next_if_keyword() == Some(Keyword::Nan) {
                        ast::Literal::Float(f64::NAN)
                    } else {
                        return Err(errinput!("expected NULL or NAN"));
                    };
                    if neg {
                        ast::Expression::Operator(ast::Operator::Not(Box::new(
                            ast::Expression::Operator(ast::Operator::Is(
                                Box::new(ast::Expression::All),
                                lit,
                            )),
                        )))
                    } else {
                        ast::Expression::Operator(ast::Operator::Is(Box::new(ast::Expression::All), lit))
                    }
                }
                _ => return Err(errinput!("unexpected keyword {kw}")),
            });
        }

        if self.next_is(Token::Minus) {
            let expr = self.parse_expression_atom()?;
            return Ok(ast::Expression::Operator(ast::Operator::Negate(Box::new(expr))));
        }

        if self.next_is(Token::Plus) {
            let expr = self.parse_expression_atom()?;
            return Ok(ast::Expression::Operator(ast::Operator::Identity(Box::new(expr))));
        }

        if let Some(Token::Number(s)) = self.lexer.next() {
            return Ok(ast::Expression::Literal(match s.chars().position(|c| c == '.') {
                Some(_) => ast::Literal::Float(s.parse().map_err(|_| errinput!("invalid float"))?),
                None => ast::Literal::Integer(s.parse().map_err(|_| errinput!("invalid integer"))?),
            }));
        }

        if let Some(Token::String(s)) = self.lexer.next() {
            return Ok(ast::Expression::Literal(ast::Literal::String(s)));
        }

        if self.next_is(Token::Asterisk) {
            return Ok(ast::Expression::All);
        }

        let table = self.next_ident()?;
        if self.next_is(Token::Period) {
            let column = self.next_ident()?;
            Ok(ast::Expression::Column(Some(table), column))
        } else {
            Ok(ast::Expression::Column(None, table))
        }
    }

    /// Parses an expression list (comma-separated expressions).
    fn parse_expression_list(&mut self) -> Result<Vec<ast::Expression>> {
        let mut exprs = Vec::new();
        exprs.push(self.parse_expression()?);
        while self.next_is(Token::Comma) {
            exprs.push(self.parse_expression()?);
        }
        Ok(exprs)
    }

    /// Parses a prefix operator, if there is one and its precedence is at least
    /// min_precedence.
    fn parse_prefix_operator_at(&mut self, min_precedence: Precedence) -> Option<PrefixOperator> {
        if let Some(kw) = self.next_if_keyword() {
            return match kw {
                Keyword::Not => Some(PrefixOperator::Not),
                Keyword::Is => {
                    let neg = self.next_if_keyword() == Some(Keyword::Not);
                    let lit = if self.next_if_keyword() == Some(Keyword::Null) {
                        ast::Literal::Null
                    } else if self.next_if_keyword() == Some(Keyword::Nan) {
                        ast::Literal::Float(f64::NAN)
                    } else {
                        return None;
                    };
                    if neg {
                        Some(PrefixOperator::Not)
                    } else {
                        None
                    }
                }
                _ => None,
            };
        }

        if self.next_is(Token::Minus) {
            return Some(PrefixOperator::Minus);
        }

        if self.next_is(Token::Plus) {
            return Some(PrefixOperator::Plus);
        }

        None
    }

    /// Parses an infix operator, if there is one and its precedence is at least
    /// min_precedence.
    fn parse_infix_operator_at(&mut self, min_precedence: Precedence) -> Option<InfixOperator> {
        if let Some(kw) = self.next_if_keyword() {
            return match kw {
                Keyword::And => Some(InfixOperator::And),
                Keyword::Or => Some(InfixOperator::Or),
                Keyword::Like => Some(InfixOperator::Like),
                _ => None,
            };
        }

        if self.next_is(Token::Equal) {
            return Some(InfixOperator::Equal);
        }

        if self.next_is(Token::NotEqual) {
            return Some(InfixOperator::NotEqual);
        }

        if self.next_is(Token::GreaterThan) {
            return Some(InfixOperator::GreaterThan);
        }

        if self.next_is(Token::GreaterThanOrEqual) {
            return Some(InfixOperator::GreaterThanOrEqual);
        }

        if self.next_is(Token::LessThan) {
            return Some(InfixOperator::LessThan);
        }

        if self.next_is(Token::LessThanOrEqual) {
            return Some(InfixOperator::LessThanOrEqual);
        }

        if self.next_is(Token::Plus) {
            return Some(InfixOperator::Add);
        }

        if self.next_is(Token::Minus) {
            return Some(InfixOperator::Subtract);
        }

        if self.next_is(Token::Asterisk) {
            return Some(InfixOperator::Multiply);
        }

        if self.next_is(Token::Slash) {
            return Some(InfixOperator::Divide);
        }

        if self.next_is(Token::Caret) {
            return Some(InfixOperator::Exponentiate);
        }

        if self.next_is(Token::Percent) {
            return Some(InfixOperator::Remainder);
        }

        None
    }

    /// Parses a postfix operator, if there is one and its precedence is at
    /// least min_precedence.
    fn parse_postfix_operator_at(
        &mut self,
        min_precedence: Precedence,
    ) -> Result<Option<PostfixOperator>> {
        if self.next_is(Token::Exclamation) {
            return Ok(Some(PostfixOperator::Factorial));
        }

        if self.next_is(Token::Keyword(Keyword::Is)) {
            let neg = self.next_is(Token::Keyword(Keyword::Not));
            let lit = if self.next_is(Token::Keyword(Keyword::Null)) {
                ast::Literal::Null
            } else if self.next_is(Token::Keyword(Keyword::Nan)) {
                ast::Literal::Float(f64::NAN)
            } else {
                return Err(errinput!("expected NULL or NAN"));
            };
            return Ok(Some(if neg {
                PostfixOperator::IsNot(lit)
            } else {
                PostfixOperator::Is(lit)
            }));
        }

        Ok(None)
    }
}

/// Operator precedence.
type Precedence = u8;

/// Operator associativity.
enum Associativity {
    Left,
    Right,
}

impl Add<Associativity> for Precedence {
    type Output = Self;

    fn add(self, rhs: Associativity) -> Self {
        match rhs {
            Associativity::Left => self + 1,
            Associativity::Right => self,
        }
    }
}

/// Prefix operators.
enum PrefixOperator {
    Minus, // -a
    Not,   // NOT a
    Plus,  // +a
}

impl PrefixOperator {
    /// The operator precedence.
    fn precedence(&self) -> Precedence {
        100
    }

    // The operator associativity. Prefix operators are right-associative by
    // definition.
    fn associativity(&self) -> Associativity {
        Associativity::Right
    }

    /// Builds an AST expression for the operator.
    fn into_expression(self, rhs: ast::Expression) -> ast::Expression {
        match self {
            Self::Minus => ast::Expression::Operator(ast::Operator::Negate(Box::new(rhs))),
            Self::Not => ast::Expression::Operator(ast::Operator::Not(Box::new(rhs))),
            Self::Plus => ast::Expression::Operator(ast::Operator::Identity(Box::new(rhs))),
        }
    }
}

/// Infix operators.
enum InfixOperator {
    Add,                // a + b
    And,                // a AND b
    Divide,             // a / b
    Equal,              // a = b
    Exponentiate,       // a ^ b
    GreaterThan,        // a > b
    GreaterThanOrEqual, // a >= b
    LessThan,           // a < b
    LessThanOrEqual,    // a <= b
    Like,               // a LIKE b
    Multiply,           // a * b
    NotEqual,           // a != b
    Or,                 // a OR b
    Remainder,          // a % b
    Subtract,           // a - b
}

impl InfixOperator {
    /// The operator precedence.
    fn precedence(&self) -> Precedence {
        match self {
            Self::Or => 10,
            Self::And => 20,
            Self::Equal | Self::NotEqual | Self::LessThan | Self::LessThanOrEqual
            | Self::GreaterThan | Self::GreaterThanOrEqual | Self::Like => 30,
            Self::Add | Self::Subtract => 40,
            Self::Multiply | Self::Divide | Self::Remainder => 50,
            Self::Exponentiate => 60,
        }
    }

    /// The operator associativity.
    fn associativity(&self) -> Associativity {
        Associativity::Left
    }

    /// Builds an AST expression for the infix operator.
    fn into_expression(self, lhs: ast::Expression, rhs: ast::Expression) -> ast::Expression {
        use ast::Operator::*;
        match self {
            Self::Add => Operator::Add(Box::new(lhs), Box::new(rhs)),
            Self::And => Operator::And(Box::new(lhs), Box::new(rhs)),
            Self::Divide => Operator::Divide(Box::new(lhs), Box::new(rhs)),
            Self::Equal => Operator::Equal(Box::new(lhs), Box::new(rhs)),
            Self::Exponentiate => Operator::Exponentiate(Box::new(lhs), Box::new(rhs)),
            Self::GreaterThan => Operator::GreaterThan(Box::new(lhs), Box::new(rhs)),
            Self::GreaterThanOrEqual => Operator::GreaterThanOrEqual(Box::new(lhs), Box::new(rhs)),
            Self::LessThan => Operator::LessThan(Box::new(lhs), Box::new(rhs)),
            Self::LessThanOrEqual => Operator::LessThanOrEqual(Box::new(lhs), Box::new(rhs)),
            Self::Like => Operator::Like(Box::new(lhs), Box::new(rhs)),
            Self::Multiply => Operator::Multiply(Box::new(lhs), Box::new(rhs)),
            Self::NotEqual => Operator::NotEqual(Box::new(lhs), Box::new(rhs)),
            Self::Or => Operator::Or(Box::new(lhs), Box::new(rhs)),
            Self::Remainder => Operator::Remainder(Box::new(lhs), Box::new(rhs)),
            Self::Subtract => Operator::Subtract(Box::new(lhs), Box::new(rhs)),
        }
        .into()
    }
}

/// Postfix operators.
enum PostfixOperator {
    Factorial,           // a!
    Is(ast::Literal),    // a IS NULL | NAN
    IsNot(ast::Literal), // a IS NOT NULL | NAN
}

impl PostfixOperator {
    // The operator precedence.
    fn precedence(&self) -> Precedence {
        70
    }

    /// Builds an AST expression for the operator.
    fn into_expression(self, lhs: ast::Expression) -> ast::Expression {
        use ast::Operator::*;
        match self {
            Self::Factorial => Operator::Factorial(Box::new(lhs)).into(),
            Self::Is(lit) => Operator::Is(Box::new(lhs), lit).into(),
            Self::IsNot(lit) => Operator::Not(Box::new(Operator::Is(Box::new(lhs), lit).into())).into(),
        }
    }
}

